// src/pages/Finance.jsx
import React, { useState, useEffect } from 'react';
import { useClaim } from '../hooks/useClaim.js';
import { useAuth } from '../hooks/useAuth.js';
import { CLAIM_STATUS, CLAIM_STATUS_LABELS, CLAIM_STATUS_COLORS, CLAIM_TYPE } from '../constants/claimStatus.js';
import './Finance.css';

const Finance = () => {
  const { user } = useAuth();
  const { claims } = useClaim();
  
  // ============================================================
  // STATE MANAGEMENT
  // ============================================================
  
  // Filter states
  const [filterType, setFilterType] = useState('all'); // 'all', 'replacement', 'repair'
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  
  // Loading and export states
  const [isExporting, setIsExporting] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  
  // Selected claim for screenshot view
  const [selectedClaim, setSelectedClaim] = useState(null);
  const [showScreenshotModal, setShowScreenshotModal] = useState(false);
  
  // ============================================================
  // DATA FETCHING (Comment for backend integration)
  // ============================================================
  
  /*
    ============================================================
    BACKEND INTEGRATION NOTES:
    ============================================================
    
    1. Get latest claims (5-7 claims):
       const response = await fetch('/api/claims/latest?limit=7');
       const data = await response.json();
       setLatestClaims(data.claims);
    
    2. For filtering by date:
       const response = await fetch(
         `/api/claims/export?startDate=${startDate}&endDate=${endDate}`
       );
    
    3. For filtering by type:
       const response = await fetch(
         `/api/claims/export?type=${filterType}`
       );
    
    4. For export all:
       const response = await fetch('/api/claims/export/all');
  */
  
  // Get all claims (simulated)
  const allClaims = claims || [];
  
  // Get latest 5-7 claims
  const getLatestClaims = (limit = 7) => {
    const sorted = [...allClaims].sort((a, b) => {
      const dateA = new Date(a.created_at || a.insuranceClaimDate);
      const dateB = new Date(b.created_at || b.insuranceClaimDate);
      return dateB - dateA;
    });
    return sorted.slice(0, limit);
  };
  
  // ============================================================
  // FILTERING LOGIC
  // ============================================================
  
  /**
   * Filter claims based on type and date range
   * This will be replaced by API filtering when backend is ready
   */
  const getFilteredClaims = () => {
    let filtered = [...allClaims];
    
    // Filter by claim type
    if (filterType === 'replacement') {
      filtered = filtered.filter(c => c.claim_type === CLAIM_TYPE.REPLACEMENT);
    } else if (filterType === 'repair') {
      filtered = filtered.filter(c => c.claim_type === CLAIM_TYPE.REPAIR);
    }
    
    // Filter by date range
    if (startDate) {
      const start = new Date(startDate);
      filtered = filtered.filter(c => {
        const claimDate = new Date(c.created_at || c.insuranceClaimDate);
        return claimDate >= start;
      });
    }
    if (endDate) {
      const end = new Date(endDate);
      end.setHours(23, 59, 59);
      filtered = filtered.filter(c => {
        const claimDate = new Date(c.created_at || c.insuranceClaimDate);
        return claimDate <= end;
      });
    }
    
    // Filter by search term (cover note or customer name)
    if (searchTerm) {
      const term = searchTerm.toLowerCase();
      filtered = filtered.filter(c => 
        c.covernoteRefNumber?.toLowerCase().includes(term) ||
        c.customerName?.toLowerCase().includes(term) ||
        c.msisdn?.includes(term)
      );
    }
    
    // Sort by date descending (newest first)
    filtered.sort((a, b) => {
      const dateA = new Date(a.created_at || a.insuranceClaimDate);
      const dateB = new Date(b.created_at || b.insuranceClaimDate);
      return dateB - dateA;
    });
    
    return filtered;
  };
  
  // ============================================================
  // COMPUTED VALUES
  // ============================================================
  
  const latestClaims = getLatestClaims(7);
  const filteredClaims = getFilteredClaims();
  
  // Stats for display
  const stats = {
    total: allClaims.length,
    latest: latestClaims.length,
    replacement: allClaims.filter(c => c.claim_type === CLAIM_TYPE.REPLACEMENT).length,
    repair: allClaims.filter(c => c.claim_type === CLAIM_TYPE.REPAIR).length,
    excess: allClaims.filter(c => c.claim_subtype === 'Excess').length,
    verified: allClaims.filter(c => c.status === CLAIM_STATUS.VERIFIED).length
  };
  
  // ============================================================
  // HANDLER FUNCTIONS
  // ============================================================
  
  /**
   * Handle view screenshot
   */
  const handleViewScreenshot = (claim) => {
    setSelectedClaim(claim);
    setShowScreenshotModal(true);
  };
  
  /**
   * Handle clear all filters
   */
  const handleClearFilters = () => {
    setFilterType('all');
    setStartDate('');
    setEndDate('');
    setSearchTerm('');
  };
  
  /**
   * Handle export based on current filters
   * In production:
   * const response = await fetch('/api/claims/export', {
   *   method: 'POST',
   *   headers: { 'Content-Type': 'application/json' },
   *   body: JSON.stringify({
   *     type: filterType,
   *     startDate,
   *     endDate,
   *     format: 'csv'
   *   })
   * });
   * const blob = await response.blob();
   * const url = window.URL.createObjectURL(blob);
   * const a = document.createElement('a');
   * a.href = url;
   * a.download = `claims_${new Date().toISOString().slice(0,10)}.csv`;
   * a.click();
   */
  const handleExportCSV = () => {
    setIsExporting(true);
    
    // Simulate export delay
    setTimeout(() => {
      try {
        // Get data to export (all filtered claims or all if no filters)
        const dataToExport = filteredClaims.length > 0 ? filteredClaims : allClaims;
        
        // Define CSV headers
        const headers = [
          'Cover Note',
          'Customer',
          'Phone',
          'IMEI',
          'Model',
          'Type',
          'Subtype',
          'Status',
          'Amount',
          'Transaction ID',
          'Transaction Date',
          'Claim Date',
          'Program',
          'Agent'
        ];
        
        // Create CSV rows
        const rows = dataToExport.map(claim => [
          claim.covernoteRefNumber || 'N/A',
          claim.customerName || 'N/A',
          claim.msisdn || 'N/A',
          claim.imeiNumber || 'N/A',
          claim.model || 'N/A',
          claim.claim_type || 'N/A',
          claim.claim_subtype || 'N/A',
          CLAIM_STATUS_LABELS[claim.status] || claim.status || 'N/A',
          claim.total_amount ? `"${claim.total_amount.toLocaleString()}"` : 'N/A',
          claim.transaction_id || 'N/A',
          claim.transaction_date || 'N/A',
          claim.insuranceClaimDate || claim.created_at || 'N/A',
          claim.program || 'N/A',
          claim.representative || 'N/A'
        ]);
        
        // Combine headers and rows
        const csvContent = [
          headers.join(','),
          ...rows.map(row => row.join(','))
        ].join('\n');
        
        // Create download
        const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement('a');
        const url = URL.createObjectURL(blob);
        link.href = url;
        
        // Generate filename with filters
        let filename = 'claims_export';
        if (filterType !== 'all') {
          filename += `_${filterType}`;
        }
        if (startDate || endDate) {
          filename += `_${startDate || 'start'}_to_${endDate || 'end'}`;
        }
        filename += `_${new Date().toISOString().slice(0,10)}.csv`;
        
        link.download = filename;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
        
        alert(`✅ CSV exported successfully! (${dataToExport.length} claims)`);
      } catch (error) {
        console.error('Export error:', error);
        alert('❌ Error exporting CSV. Please try again.');
      } finally {
        setIsExporting(false);
      }
    }, 1000);
  };
  
  /**
   * Handle export all claims
   */
  const handleExportAll = () => {
    if (window.confirm('Export all claims?')) {
      // Temporarily reset filters for export
      const currentType = filterType;
      const currentStart = startDate;
      const currentEnd = endDate;
      
      setFilterType('all');
      setStartDate('');
      setEndDate('');
      
      setTimeout(() => {
        handleExportCSV();
        // Restore filters
        setFilterType(currentType);
        setStartDate(currentStart);
        setEndDate(currentEnd);
      }, 100);
    }
  };
  
  /**
   * Handle export by type
   */
  const handleExportByType = (type) => {
    if (window.confirm(`Export all ${type} claims?`)) {
      const currentType = filterType;
      setFilterType(type);
      
      setTimeout(() => {
        handleExportCSV();
        setFilterType(currentType);
      }, 100);
    }
  };
  
  // ============================================================
  // RENDER HELPERS
  // ============================================================
  
  /**
   * Get status badge
   */
  const getStatusBadge = (status) => {
    const color = CLAIM_STATUS_COLORS[status] || '#95a5a6';
    const label = CLAIM_STATUS_LABELS[status] || status || 'N/A';
    return (
      <span className="status-badge" style={{ backgroundColor: color }}>
        {label}
      </span>
    );
  };
  
  /**
   * Get type badge
   */
  const getTypeBadge = (claim) => {
    const type = claim.claim_type || 'N/A';
    const subtype = claim.claim_subtype || '';
    const isExcess = subtype === 'Excess';
    const className = `type-badge ${type?.toLowerCase()} ${isExcess ? 'excess' : ''}`;
    return (
      <span className={className}>
        {type} {subtype && `· ${subtype}`}
      </span>
    );
  };
  
  /**
   * Format date
   */
  const formatDate = (dateString) => {
    if (!dateString) return 'N/A';
    try {
      const date = new Date(dateString);
      return date.toLocaleDateString('en-US', {
        year: 'numeric',
        month: 'short',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit'
      });
    } catch {
      return dateString;
    }
  };
  
  /**
   * Format currency
   */
  const formatCurrency = (amount) => {
    if (!amount) return 'N/A';
    return `TZS ${amount.toLocaleString()}`;
  };
  
  // ============================================================
  // RENDER
  // ============================================================
  
  return (
    <div className="finance-page">
      {/* ============================================================
          HEADER
          ============================================================ */}
      <div className="finance-header">
        <div className="finance-header-content">
          <i className="fas fa-coins"></i>
          <h2>Finance Dashboard</h2>
          <span className="finance-subtitle">View and export claims</span>
        </div>
        <div className="finance-actions">
          <button 
            className="btn-primary export-btn"
            onClick={handleExportCSV}
            disabled={isExporting}
          >
            {isExporting ? (
              <><i className="fas fa-spinner fa-spin"></i> Exporting...</>
            ) : (
              <><i className="fas fa-file-export"></i> Export Filtered</>
            )}
          </button>
          <button 
            className="btn-outline export-all-btn"
            onClick={handleExportAll}
            disabled={isExporting}
          >
            <i className="fas fa-download"></i> Export All
          </button>
        </div>
      </div>
      
      {/* ============================================================
          STATS BANNER
          ============================================================ */}
      <div className="stats-banner">
        <div className="stat-item">
          <span className="stat-label">Total Claims</span>
          <span className="stat-value">{stats.total}</span>
        </div>
        <div className="stat-divider"></div>
        <div className="stat-item">
          <span className="stat-label">Latest</span>
          <span className="stat-value">{stats.latest}</span>
        </div>
        <div className="stat-divider"></div>
        <div className="stat-item">
          <span className="stat-label">Replacement</span>
          <span className="stat-value">{stats.replacement}</span>
        </div>
        <div className="stat-divider"></div>
        <div className="stat-item">
          <span className="stat-label">Repair</span>
          <span className="stat-value">{stats.repair}</span>
        </div>
        <div className="stat-divider"></div>
        <div className="stat-item">
          <span className="stat-label">Excess</span>
          <span className="stat-value">{stats.excess}</span>
        </div>
        <div className="stat-divider"></div>
        <div className="stat-item">
          <span className="stat-label">Verified</span>
          <span className="stat-value">{stats.verified}</span>
        </div>
      </div>
      
      {/* ============================================================
          LATEST CLAIMS SECTION
          ============================================================ */}
      <div className="finance-section">
        <div className="section-header">
          <div className="section-title">
            <i className="fas fa-clock"></i>
            <h3>Latest Claims</h3>
            <span className="section-badge">Last {stats.latest} claims</span>
          </div>
          <div className="section-actions">
            <button 
              className="btn-outline small"
              onClick={() => {
                setFilterType('all');
                setStartDate('');
                setEndDate('');
                setSearchTerm('');
              }}
            >
              <i className="fas fa-sync"></i> Reset
            </button>
          </div>
        </div>
        <div className="latest-claims-list">
          {latestClaims.length === 0 ? (
            <div className="empty-state">
              <i className="fas fa-inbox"></i>
              <p>No claims found</p>
            </div>
          ) : (
            latestClaims.map(claim => (
              <div key={claim.id} className="latest-claim-item">
                <div className="claim-info">
                  <span className="claim-ref">{claim.covernoteRefNumber}</span>
                  <span className="claim-customer">{claim.customerName}</span>
                  <span className="claim-type">{getTypeBadge(claim)}</span>
                </div>
                <div className="claim-meta">
                  {getStatusBadge(claim.status)}
                  <span className="claim-amount">{formatCurrency(claim.total_amount)}</span>
                  <span className="claim-date">{formatDate(claim.created_at || claim.insuranceClaimDate)}</span>
                  {claim.screenshot && (
                    <button 
                      className="action-btn view"
                      onClick={() => handleViewScreenshot(claim)}
                      title="View Screenshot"
                    >
                      <i className="fas fa-image"></i>
                    </button>
                  )}
                </div>
              </div>
            ))
          )}
        </div>
      </div>
      
      {/* ============================================================
          FILTER & EXPORT SECTION
          ============================================================ */}
      <div className="finance-container">
        <div className="finance-filters">
          <div className="filter-group">
            <label>Claim Type</label>
            <select 
              className="filter-select"
              value={filterType}
              onChange={(e) => setFilterType(e.target.value)}
            >
              <option value="all">All Types</option>
              <option value="replacement">Replacement</option>
              <option value="repair">Repair</option>
            </select>
          </div>
          
          <div className="filter-group">
            <label>Start Date</label>
            <input
              type="date"
              className="filter-input"
              value={startDate}
              onChange={(e) => setStartDate(e.target.value)}
            />
          </div>
          
          <div className="filter-group">
            <label>End Date</label>
            <input
              type="date"
              className="filter-input"
              value={endDate}
              onChange={(e) => setEndDate(e.target.value)}
            />
          </div>
          
          <div className="filter-group search-group">
            <label>Search</label>
            <div className="search-box">
              <i className="fas fa-search"></i>
              <input
                type="text"
                placeholder="Search cover note, customer..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
              {searchTerm && (
                <button className="clear-search" onClick={() => setSearchTerm('')}>
                  <i className="fas fa-times"></i>
                </button>
              )}
            </div>
          </div>
          
          <div className="filter-actions">
            <button className="btn-outline small" onClick={handleClearFilters}>
              <i className="fas fa-undo"></i> Clear
            </button>
            <button 
              className="btn-primary small" 
              onClick={handleExportCSV}
              disabled={isExporting}
            >
              <i className="fas fa-file-export"></i> Export
            </button>
          </div>
        </div>
        
        {/* ============================================================
            RESULTS SUMMARY
            ============================================================ */}
        <div className="results-summary">
          <span>
            Found <strong>{filteredClaims.length}</strong> claims
            {filterType !== 'all' && ` · Type: ${filterType}`}
            {(startDate || endDate) && ' · Date filtered'}
            {searchTerm && ` · Search: "${searchTerm}"`}
          </span>
          <div className="quick-export">
            <button 
              className="btn-outline small"
              onClick={() => handleExportByType('replacement')}
              disabled={isExporting}
            >
              <i className="fas fa-exchange-alt"></i> Export Replacement
            </button>
            <button 
              className="btn-outline small"
              onClick={() => handleExportByType('repair')}
              disabled={isExporting}
            >
              <i className="fas fa-tools"></i> Export Repair
            </button>
          </div>
        </div>
        
        {/* ============================================================
            CLAIMS TABLE
            ============================================================ */}
        <div className="finance-list">
          {filteredClaims.length === 0 ? (
            <div className="empty-state">
              <i className="fas fa-inbox"></i>
              <p>No claims found matching your filters</p>
              <button className="btn-outline small" onClick={handleClearFilters}>
                Clear Filters
              </button>
            </div>
          ) : (
            <table className="finance-table">
              <thead>
                <tr>
                  <th>Cover Note</th>
                  <th>Customer</th>
                  <th>Phone</th>
                  <th>Type</th>
                  <th>Status</th>
                  <th>Amount</th>
                  <th>Transaction</th>
                  <th>Date</th>
                  <th>Screenshot</th>
                </tr>
              </thead>
              <tbody>
                {filteredClaims.map(claim => (
                  <tr key={claim.id}>
                    <td className="claim-ref">{claim.covernoteRefNumber}</td>
                    <td>{claim.customerName}</td>
                    <td>{claim.msisdn}</td>
                    <td>{getTypeBadge(claim)}</td>
                    <td>{getStatusBadge(claim.status)}</td>
                    <td className="amount-cell">{formatCurrency(claim.total_amount)}</td>
                    <td>{claim.transaction_id || 'N/A'}</td>
                    <td>{formatDate(claim.created_at || claim.insuranceClaimDate)}</td>
                    <td>
                      {claim.screenshot ? (
                        <button 
                          className="action-btn view"
                          onClick={() => handleViewScreenshot(claim)}
                          title="View Screenshot"
                        >
                          <i className="fas fa-image"></i>
                        </button>
                      ) : (
                        <span className="no-screenshot-text">N/A</span>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>
      
      {/* ============================================================
          SCREENSHOT MODAL
          ============================================================ */}
      {showScreenshotModal && selectedClaim && selectedClaim.screenshot && (
        <div className="modal-overlay" onClick={() => setShowScreenshotModal(false)}>
          <div className="modal-content screenshot-modal" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h3>Transaction Screenshot</h3>
              <button className="modal-close" onClick={() => setShowScreenshotModal(false)}>
                <i className="fas fa-times"></i>
              </button>
            </div>
            <div className="modal-body">
              <div className="screenshot-info">
                <p><strong>Claim:</strong> {selectedClaim.covernoteRefNumber}</p>
                <p><strong>Transaction ID:</strong> {selectedClaim.transaction_id}</p>
                <p><strong>Amount:</strong> {formatCurrency(selectedClaim.total_amount)}</p>
                <p><strong>Customer:</strong> {selectedClaim.customerName}</p>
                <p><strong>Date:</strong> {formatDate(selectedClaim.transaction_date)}</p>
              </div>
              <div className="screenshot-container">
                <img 
                  src={selectedClaim.screenshot} 
                  alt="Transaction Screenshot" 
                  className="screenshot-image"
                  onError={(e) => {
                    e.target.style.display = 'none';
                    e.target.parentElement.innerHTML = '<div class="no-screenshot"><i class="fas fa-image"></i><p>Screenshot not available</p></div>';
                  }}
                />
              </div>
            </div>
            <div className="modal-footer">
              <button className="btn-outline" onClick={() => setShowScreenshotModal(false)}>
                Close
              </button>
            </div>
          </div>
        </div>
      )}
      
      {/* ============================================================
          BACKEND INTEGRATION GUIDE
          ============================================================ */}
      <div className="backend-guide" style={{ display: 'none' }}>
        {`
          ============================================================
          BACKEND INTEGRATION GUIDE - FINANCE
          ============================================================
          
          API Endpoints Needed:
          
          1. GET /api/claims/latest?limit=7
             Response: { claims: [{ ... }] }
          
          2. GET /api/claims/export
             Query params:
             - type: 'all' | 'replacement' | 'repair'
             - startDate: ISO date string (YYYY-MM-DD)
             - endDate: ISO date string (YYYY-MM-DD)
             - search: string
             
             Response: CSV file download
          
          3. GET /api/claims/export/all
             Response: CSV file download (all claims)
          
          ============================================================
          DATABASE QUERIES (MySQL)
          ============================================================
          
          -- Get latest claims
          SELECT * FROM claims 
          ORDER BY created_at DESC 
          LIMIT 7;
          
          -- Export claims with filters
          SELECT * FROM claims 
          WHERE (claim_type = ? OR ? = 'all')
          AND (created_at >= ? OR ? IS NULL)
          AND (created_at <= ? OR ? IS NULL)
          AND (customer_name LIKE ? OR covernote_number LIKE ?)
          ORDER BY created_at DESC;
          
          -- Get claim counts
          SELECT 
            COUNT(*) as total,
            SUM(CASE WHEN claim_type = 'Replacement' THEN 1 ELSE 0 END) as replacement,
            SUM(CASE WHEN claim_type = 'Repair' THEN 1 ELSE 0 END) as repair,
            SUM(CASE WHEN claim_subtype = 'Excess' THEN 1 ELSE 0 END) as excess,
            SUM(CASE WHEN status = 'VERIFIED' THEN 1 ELSE 0 END) as verified
          FROM claims;
        `}
      </div>
    </div>
  );
};

export default Finance;
